import { defineConfig, devices } from '@playwright/test';

/**
 * Dashboard end-to-end tests (plan §7, ADR-0043) against the Docker stack that scripts/e2e.sh starts:
 * public listener on :8080, admin listener (API + UI) on 127.0.0.1:9090.
 * Deterministic by design: no retries, one worker, traffic generated by the tests themselves.
 */
export default defineConfig({
  testDir: 'tests/e2e',
  testMatch: '**/*.spec.ts',
  fullyParallel: false,
  workers: 1,
  retries: 0,
  forbidOnly: process.env['CI'] !== undefined,
  timeout: 30_000,
  expect: { timeout: 10_000 },
  reporter: [['list'], ['html', { open: 'never', outputFolder: 'playwright-report' }]],
  outputDir: 'test-results',
  use: {
    baseURL: process.env['E2E_ADMIN_URL'] ?? 'http://127.0.0.1:9090',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: [{ name: 'chromium', use: { ...devices['Desktop Chrome'] } }],
});
